) AS (
  VALUES 
    (368::BIGINT, 'El peor profesor de la escuela no ayuda a los estudiantes, es demasiado cerrado y contradictorio, cuando se le hace consultas más bien lo deja más enredado a uno, las calificaciones de los proyectos es a puro criterio del mae y no se entiende que pide en su totalidad'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas', 'Muchos proyectos grupales']::TEXT[], '2024-11-06T00:00:00+00:00'::TIMESTAMPTZ, '7f872f358928f1a9b322273118feb1de3507163a1d2ffdd10f862365636b659d'::TEXT, ARRAY[1237]::BIGINT[]),
    (368::BIGINT, 'No lo recomiendo, no define el alcance de un proyecto que vale más de la mitad de la nota. Calificación sin criterios. Baja ptos de la nada. Se contradice. No tiene nada de vocación. Calificación poco clara.'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clase fácil', 'Asistencia obligatoria']::TEXT[], '2022-10-19T00:00:00+00:00'::TIMESTAMPTZ, '9c33a65ac1a3372054cdc72967cdcf8d41fee31a7592ec685988c5ad3aa0959d'::TEXT, ARRAY[1237]::BIGINT[]),
    (368::BIGINT, 'Sabe mucho, pero no tiene la habilidad de transmitir ese conocimiento a los estudiantes, las clases son un monólogo, son largas y cansadas, hay que dedicar mucho tiempo por aparte y palmarla si se quiere pasar'::TEXT, 2.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-06-27T00:00:00+00:00'::TIMESTAMPTZ, 'd29acc01d2bb81537b490b5dd73507306ca4eb5e4377949854024818b1cae9e4'::TEXT, ARRAY[1202]::BIGINT[]),
    (368::BIGINT, 'Una porquería de profesor no ayuda y piensa que enseña algo. Inútil'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('55','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clase fácil', 'Exámenes retadores']::TEXT[], '2022-06-17T00:00:00+00:00'::TIMESTAMPTZ, '9b47955020958a3787488509325257940f94a20af0b927fb709e9f80ac5d0058'::TEXT, ARRAY[1202]::BIGINT[]),
    (368::BIGINT, 'Puede saber mucho pero es un bostezo'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-05-18T00:00:00+00:00'::TIMESTAMPTZ, 'b4c894f17c276cdf6cba18f7232871533648de8fe35f9b0a7a3c3e86008010da'::TEXT, ARRAY[1202]::BIGINT[]),
    (368::BIGINT, 'El curso ahora es diferente y mas llevadero, es mas que todo de como utilizar programas de modelado. Todo bien con el curso hasta que al profe se le ocurre hacer un proyecto de programar una aplicación que resuelva algún problema de estructura(no tiene de requisito taller 1).'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2022-03-23T00:00:00+00:00'::TIMESTAMPTZ, '36cf4b01d4a1cdf9de68217e2aaafd1c3a0440d33d2c7cfb55bfee95f1e97e1c'::TEXT, ARRAY[1202]::BIGINT[]),
    (368::BIGINT, 'Solo da la primera clase, todo es asincrónico. Exámenes muy duros, pero hace curvas. Es lo que hay así que no se pude hacer mucho.'::TEXT, 2.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Exámenes retadores']::TEXT[], '2021-07-29T00:00:00+00:00'::TIMESTAMPTZ, '335e65c701e3068fc4190298fe5958b115b4d2a7e8649431610089a98673c65f'::TEXT, ARRAY[1202]::BIGINT[]),
    (368::BIGINT, 'Le da pereza bretear, no da clases. Explica muy bien eso sí, pero ejemplos muy sencillos que nada que ver a lo que deja en las tareas o en los exámenes, que son ejercicios de otro nivel. Hay que estudiar con exámenes viejos si quiere pasar.'::TEXT, 2.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-07-19T00:00:00+00:00'::TIMESTAMPTZ, 'a8b1b4734f12910359608ff4707ea268b72ef6b8fefe61495f2bb0f5bac8ab96'::TEXT, ARRAY[1202]::BIGINT[]),
    (368::BIGINT, 'Asincrónico 100%, clases grabadas de otros semestres (lo cual da vergüenza), ayuda en los exámenes con curvas o dando más tiempo. Se debe ser autodidacta y estudiar mucho por otros medios, tener un buen grupo de trabajo ayuda porque algunas evaluaciones son grupales.'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2021-07-03T00:00:00+00:00'::TIMESTAMPTZ, '04526727b936a0d1da99da5bff88e7cf3466a2b2bd6500594ce2c8b8b503a3bc'::TEXT, ARRAY[1202]::BIGINT[]),
    (368::BIGINT, 'Clases 100% asincrónicas, son videos de semestres pasados, si se lleva la materia al día se pasa bien, en consulta el profe es un toque cortante, se debe tener cuidado con ciertos comentarios, en ocasiones realiza curva.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2021-07-01T00:00:00+00:00'::TIMESTAMPTZ, '13f7e1760f008e32ec1b8ce74de9e3dc1d7155df7e029530bd6fb7acd4f72e21'::TEXT, ARRAY[1202]::BIGINT[]),
    (368::BIGINT, 'Todas las clases son asincrónicas, y son videos de semestres pasados, se debe ser muy autodidacta para entender bien y practicar un montón. Recomiendo armar un buen grupo ya que algunas evaluaciones son grupales.'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores']::TEXT[], '2021-06-30T00:00:00+00:00'::TIMESTAMPTZ, '889c7dff7564b3c95a10e8bb498cb2f48ef00b476aaa36b24c7c8d82a544b647'::TEXT, ARRAY[1202]::BIGINT[]),
    (368::BIGINT, 'En la modalidad virtual el profesor ha mejorado significativamente, sin embargo, sigue teniendo un trato un poco brusco con los estudiantes. Hay que pensar 2 veces antes de tratar de hacer un comentario en clase o hacer una pregunta, ya que usualmente responde de manera brusca.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Deja trabajos largos']::TEXT[], '2021-05-18T00:00:00+00:00'::TIMESTAMPTZ, 'a1dfa538654e187d4f976d029ccac8fe2afc2a63eb23fa1474fdd22aaf527ae2'::TEXT, ARRAY[1219]::BIGINT[]),
    (368::BIGINT, 'SIN PALABRAS, de lo peor en la Escuela de Construcción'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores']::TEXT[], '2021-02-05T00:00:00+00:00'::TIMESTAMPTZ, '06d5fd0a99240e1333848bd0c74ce31f0edd01adf26ad8d55940da680e52f247'::TEXT, ARRAY[1219]::BIGINT[]),
    (368::BIGINT, 'Debo decir que luego de llevar dos cursos anteriores con el profe no tenía demasiadas expectativas del curso, pero este profe en modalidad virtual se superó a sí mismo, es increíble ver como no solo mejoró montones como profe, sino que, además es el profe que me ha dado las mejores clases virtuales'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Aspectos de calificación claros', 'Clases excelentes']::TEXT[], '2020-10-13T00:00:00+00:00'::TIMESTAMPTZ, '9b0c79791175055142425f0773b6b447c2ae7e356821de8ea9c80dafefa98966'::TEXT, ARRAY[1237]::BIGINT[]),
    (368::BIGINT, 'Dió las clases asincrónicas pero dejaba videos y folletos explicativos buenos. Hay que aprovechar las consultas porque da consejos para ejercicios más difíciles.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-09-02T00:00:00+00:00'::TIMESTAMPTZ, '3644b916dff005583c5afac1b3db0ede0a4c35721a49e55b2cac7f9b449374bb'::TEXT, ARRAY[1203]::BIGINT[]),
    (368::BIGINT, 'Es un aburrido.'::TEXT, 4.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'La participación importa', 'Exámenes retadores']::TEXT[], '2019-07-21T00:00:00+00:00'::TIMESTAMPTZ, '17dff561266c3f93744de3c1846142c393e916df3bc4f4902c5ccf2c59f36fa8'::TEXT, ARRAY[1190]::BIGINT[]),
    (368::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Exámenes retadores']::TEXT[], '2019-06-23T00:00:00+00:00'::TIMESTAMPTZ, '0b633ddf589a3b6face29982b385b4046e57b979fc9ea2b15fe430705bbaecd5'::TEXT, ARRAY[1203]::BIGINT[]),
    (368::BIGINT, 'es un buen profe, ha tratado de cambiar para ser mejor y lo ha logrado, explica bien, tareas sencillas y no hace quices, exámenes duros, hay que estudiar bastante, examen 2 pídanlo para la casa y él accede, es duro pero se saca, él se preocupa por el estudiante y de ser necesario da puntos extra'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-06-09T00:00:00+00:00'::TIMESTAMPTZ, '6254620ef6c4c046fd3bbf1c69a08b39226b4e4d90a0087b4c4f52782ba6f0b3'::TEXT, ARRAY[1190]::BIGINT[]),
    (368::BIGINT, 'Es alguien que sabe bastante, pero creo que su mayor limitante es la falta de ganas para dar la clases, es alguien que parece que no le gusta lo que hace y transmite demasiada pereza'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-05-17T00:00:00+00:00'::TIMESTAMPTZ, '36cf6e16968786368bc1e2cf88e6c2391f2d0a018d71ff3848d63da596a8ab6d'::TEXT, ARRAY[1190, 1202]::BIGINT[]),
    (368::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Exámenes retadores']::TEXT[], '2018-11-25T00:00:00+00:00'::TIMESTAMPTZ, '84fd3ce99467bcd754d7c84721677c45f5d2b937c2222f7eddc3bc47781df483'::TEXT, ARRAY[1190]::BIGINT[]),
    (368::BIGINT, 'El profe explica bastante bien, y en consulta ayuda mucho. Puede parecer un toque amargado pero es buena gente. No se preocupa mucho por el estudiante, pero si el estudiante busca ayuda, el está dispuesto a ayudar.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-11-23T00:00:00+00:00'::TIMESTAMPTZ, '70fc440e50e436c811b928724bbef860a4f546ba65782406e88496d85f22c34a'::TEXT, ARRAY[1202]::BIGINT[]),
    (368::BIGINT, 'Hay que poner atención como en toda clase pero el profe se esfuerza por explicar claro y que la gente entienda. Hay que ponerle en exámenes que son un toque difíciles.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Brinda apoyo', 'Exámenes retadores']::TEXT[], '2018-09-23T00:00:00+00:00'::TIMESTAMPTZ, 'a66c7f776bbd1d99157061a3db967aca34f7f3590bf20a039c01e1366b4a52c3'::TEXT, ARRAY[1190]::BIGINT[]),
    (368::BIGINT, 'La gente exagera mucho, poniéndole atención él es muy claro explicando, y sabe bastante. Ayuda mucho también lo cual es de mucho beneficio porque la materia no es tan fácil.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-09-10T00:00:00+00:00'::TIMESTAMPTZ, '2c6eb2315ff9cd4821491b4c05241821f17848071b30e8ee4d0950f56b9732fe'::TEXT, ARRAY[1190, 1202]::BIGINT[]),
    (368::BIGINT, 'Explica bien y se esfuerza por ayudar! Si le pone, se pasa bien el curso'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-09-10T00:00:00+00:00'::TIMESTAMPTZ, 'f73417294e81909e7080d9edc1579c69fa26e7283c69ad099d96545cb48b2249'::TEXT, ARRAY[1190]::BIGINT[]),
    (368::BIGINT, '1.Clase llevadera. 2.Otro aspecto es que en la consulta uno no se siente comodo preguntando, entonces como que da miedo seguir preguntando. 3.Sí se nota que el intenta mejorar y se esfuerza de que todos entiendan la materia.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Da crédito extra', 'Aspectos de calificación claros']::TEXT[], '2018-09-10T00:00:00+00:00'::TIMESTAMPTZ, 'f37846afcb5f3faddbf8778e25e3a10e3e9935179b7816b10fe5439a65dba2fb'::TEXT, ARRAY[1190]::BIGINT[]),
    (368::BIGINT, 'La verdad que es una persona que lo intimida a uno, es un profe al que no se le puede decir nada dado que es muy temperamental, a veces la gente prefiere quedarse con la duda que hablarle por la mala cara que le pone a uno por no entender, debería dar práctica a un nivel similar a los exámenes.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Exámenes retadores']::TEXT[], '2018-09-09T00:00:00+00:00'::TIMESTAMPTZ, 'd151a00e3d079619ed99caeca361dde71ae654526dcb9ee8808f3204e0946bf9'::TEXT, ARRAY[1190]::BIGINT[]),
    (368::BIGINT, 'Las tareas ayudan mucho para el examen, además de realizar exámenes viejos. Ayuda mucho con los exámenes y el ambiente en clases es agradable, nada más en consulta no es muy bueno.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-09-09T00:00:00+00:00'::TIMESTAMPTZ, '4a01fc383a88c36a6db113c60d2ec49253de193d192261dac8385a1bc1406f09'::TEXT, ARRAY[1190]::BIGINT[]),
    (368::BIGINT, 'Se ha esforzado por ser mejor profesor, toma nota de sugerencias para desarrollar la clase de una forma mejor, los examenes los realiza con cierta dificultad normal para el curso, responde las consultas.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-09-05T00:00:00+00:00'::TIMESTAMPTZ, '1ce25c3f52323612e72f3aa55dd89bdf7904fa01f53b7f0bfd5d0baed56cac00'::TEXT, ARRAY[1190]::BIGINT[]),
    (368::BIGINT, 'Hay que agarrarle el toque al principio pero el siempre busca ayudar a los estudiantes con todo lo que puede. Los exámenes es cierto que son un poco complicados pero se logran. El ha logrado mejorar como profesor. Se nota un esfuerzo de parte de él, recomendado.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-09-03T00:00:00+00:00'::TIMESTAMPTZ, '1cdb7d10580a75809dc1bef63447f0799889fdf5df1e4a9cdf5c119885108403'::TEXT, ARRAY[1190]::BIGINT[]),
    (368::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'La participación importa', 'Inspirador']::TEXT[], '2018-08-29T00:00:00+00:00'::TIMESTAMPTZ, '8df456dcc74954f9105494f1e01222365d8197c0d313822119e87db51b16ebe9'::TEXT, ARRAY[1237]::BIGINT[]),
    (368::BIGINT, 'La verdad es mucho más amable y carismático en Sólidos II, no se suele volar tanto en los exámenes, pero de todas maneras siempre hay algo que hace que sea un profe bastante complicado'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-23T00:00:00+00:00'::TIMESTAMPTZ, 'bd4ad682c2be968fe721aa7bda438656feada5b6b2c6943c5d90f859bbbaef44'::TEXT, ARRAY[1202]::BIGINT[]),
    (368::BIGINT, 'Es un profe con un carácter complicado. Solo él da mecánica de sólidos 1 y 2. Al final uno le agarra aprecio pero no inspira como profesor. Sólidos 2 es más fácil que 1, con él...'::TEXT, 2.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'La participación importa', 'Exámenes retadores']::TEXT[], '2018-06-13T00:00:00+00:00'::TIMESTAMPTZ, '6133e0be78889f0322dcc9182f03b5408333d9d0cd6e5187824290a56e35449c'::TEXT, ARRAY[1202]::BIGINT[]),
    (368::BIGINT, 'El primer examen es fácil pero en el segundo la vuela ademas que explica algunos temas con poco o nada de interes. Al final hizo curva y paso todo el grupo'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Respetado por los estudiantes', 'Exámenes retadores']::TEXT[], '2018-01-22T00:00:00+00:00'::TIMESTAMPTZ, '752bc279cc2236654925a69abc3bed6d6561c0bdee1ccafd4c9d1ba8effbad68'::TEXT, ARRAY[1190]::BIGINT[]),
    (368::BIGINT, 'No es un profesor con el que uno pueda crear confianza, los examenes son de análisis y son muy volados comparados con lo que uno ve en clase...estudie todo lo que pueda, y vaya a consulta'::TEXT, 2.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-12-04T00:00:00+00:00'::TIMESTAMPTZ, 'ccf6f1c522229a060354d4cf4ab7cec61e5410c6c08d07147ab5435370044cc8'::TEXT, ARRAY[1190]::BIGINT[]),
    (368::BIGINT, 'Tiene un temperamento muy complicado. Él se esfuerzo por explicarnos. Él repite cuantas veces uno ocupe pero nadie le responde que no entiende. Le da énfasis a unos temas del curso y otros los ve rápido. No es un curso fácil. En consulta ayuda mucho al igual que por correo.'::TEXT, 2.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Pocos exámenes', 'Brinda apoyo']::TEXT[], '2017-11-29T00:00:00+00:00'::TIMESTAMPTZ, 'b15643dee22af870d962fa77909a29ae677e3943fd1a7c3cfec2a6a7932fb74e'::TEXT, ARRAY[1190]::BIGINT[]),
    (368::BIGINT, 'Es todo un personaje este profesor, algunas veces suele ser buena nota y otras es super repugnante, explica cosas muy simples y en los exámenes vienen problemas voladísimos, al profe parece que no le interesa mucho enseñar'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-11-28T00:00:00+00:00'::TIMESTAMPTZ, '4a9db9c06129ccbaeb399b8fb5855e8bde8d734e3dc91ad09509611ccf082d93'::TEXT, ARRAY[1190]::BIGINT[]),
    (368::BIGINT, 'Pésimo profesor con carácter bastante complicado, lo cual perjudica especialmente a sus estudiantes. Curso poco provechoso, donde no se puede disfrutar el contenido del mismo. Presenta doble discurso, muestra una personalidad diferente con profesores de la escuela de lo que realmente es.'::TEXT, 4.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura', 'Da crédito extra']::TEXT[], '2017-08-09T00:00:00+00:00'::TIMESTAMPTZ, 'dc53275274da3ca996c8620cfd0d3b870e25400aeb6ba0bdf035a542c83982a7'::TEXT, ARRAY[1190]::BIGINT[]),
    (368::BIGINT, 'Es la única opción así que no hay de otra. Es difícil comprenderle, nunca se le queda bien, no hay nada similar en los exámenes a las cosas que se ven en clases. Aunque se vaya a consulta no hay gran diferencia. Su personalidad es complicada lo cual no ayuda a tenerle confianza.'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores']::TEXT[], '2017-06-28T00:00:00+00:00'::TIMESTAMPTZ, '2d5e8fb3608ed953624e9a1407257696f3244af79718e0fec90615a7a63d8c23'::TEXT, ARRAY[1202]::BIGINT[]),
    (368::BIGINT, 'Es un arrogante... ni siquiera se levanta de la silla para hacer PROBLEMAS... explica cosas demasiado sencillas y en el examen lo entuca a uno... y según él es por culpa de los cursos anteriores que uno sale mal'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2017-06-27T00:00:00+00:00'::TIMESTAMPTZ, '1a1fe7fed325e25b9523f4360a5583fe1fa57783336133c00c25e60a35fe5106'::TEXT, ARRAY[1202]::BIGINT[]),
    (368::BIGINT, 'La materia del curso por sí sola es bastante difícil ! Hay que intentar ir bien en quices y tareas .'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Exámenes retadores']::TEXT[], '2017-06-25T00:00:00+00:00'::TIMESTAMPTZ, '5b22936090b5345d48cd4fd6a910b317dafcbd3e55648c3ba11da107f06ce887'::TEXT, ARRAY[1202]::BIGINT[]),
    (368::BIGINT, 'Claramente se aprecía que el profe es de argollas, sumamente prepotente... no explica bien los contenidos o del todo no los explica, desordenado con las fechas y lo peor es que es el unico que da el curso jaja pobre la gente de constru....'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores']::TEXT[], '2017-01-31T00:00:00+00:00'::TIMESTAMPTZ, '2d0fe11ebe5e4d952ca9fc80f34e5a345e342cea6802e9a3be55f136531ae26c'::TEXT, ARRAY[1202]::BIGINT[]),
    (368::BIGINT, 'Es un poco inmaduro'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2017-01-29T00:00:00+00:00'::TIMESTAMPTZ, 'a62a7a06dde2a42d1c6d10fa1ba71d1ee05a02a2f65519d6ec1b74f7cc05e593'::TEXT, ARRAY[1203, 1202]::BIGINT[]),
    (368::BIGINT, 'Lo peor Recien graduado y se cree toda Explica lo mas facil y en el examen la vuela y lo hace durisimo. Le falta mucho'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Exámenes retadores']::TEXT[], '2016-06-28T00:00:00+00:00'::TIMESTAMPTZ, '5948ee4042caae5ba52996a5324828fb8186589ea4b999cfd356d7255a3b8aa4'::TEXT, ARRAY[1202]::BIGINT[]),
    (368::BIGINT, 'Es un arrogante.'::TEXT, 2.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores']::TEXT[], '2016-06-27T00:00:00+00:00'::TIMESTAMPTZ, 'a2d3ab918ea190c70fcc96027b67e17620c97a2bd6b04ffd3eeafa53841e3407'::TEXT, ARRAY[1203]::BIGINT[]),
    (368::BIGINT, 'Me pareció bastante bueno, hace exámenes rudos y califica rudillo, pero se le entiende y se aprende bastante. A la hora de responder es medio amargado, eso sí.'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-06T00:00:00+00:00'::TIMESTAMPTZ, 'da351e42678294b5c8fe9f730991eaa2d7816fe4bf90e84364defbb02d4f8008'::TEXT, ARRAY[1203]::BIGINT[]),
    (368::BIGINT, 'Para mí es un excelente profesor, hace la clase interesante, exámenes difíciles pero el da lo necesario para salir bien'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Respetado por los estudiantes', 'Clases excelentes']::TEXT[], '2016-06-01T00:00:00+00:00'::TIMESTAMPTZ, '2d62a079ad44590d7f9599dd150ad677a9fe2f30caf7aaf0600dc7ccbec63cee'::TEXT, ARRAY[1202]::BIGINT[]),
    (368::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores']::TEXT[], '2016-05-19T00:00:00+00:00'::TIMESTAMPTZ, 'a35f3fe98e59ea0e5cb0705fdea60e519cd99802c9000150fc7a7ed835ac7a94'::TEXT, ARRAY[1202]::BIGINT[]),
    (368::BIGINT, 'Es malo y los exámenes durísimos pero solo el esta así que salados'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('45','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-01-24T00:00:00+00:00'::TIMESTAMPTZ, '91d5cc391eccdfb6c2a95f155fc62fc84e008528d1bbd5afe9d22ea13a243ebd'::TEXT, ARRAY[1202]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
